Method.Implementation:


set stat = ##super(.pRequest, .pResponse)
// $$$TRACE("OnMessage status: " _ stat)
return stat

	set stat = $$$OK
	set dataDirec = "/itf-share/itf-tmp/RdpCrystal/Data/"
	set rulesDirec = "/itf-share/itf-tmp/RdpCrystal/Rules/"
	#dim httpGenMsg As EnsLib.HTTP.GenericMessage

	set pResp = ##class(IHC.ITF.Request.RdpValidationResp).%New()
	Do x12MsgReq.streamContainer.Stream.Rewind()

	set flNm = ##class(%File).GetFilename(x12MsgReq.streamContainer.OriginalFilename)
	$$$TRACE("In RDP ValidateX12 " _ flNm _", Transaction: " _ x12MsgReq.transactionType)
	set fileObj = ##class(%File).%New(dataDirec _  flNm)
	set status = fileObj.Open("WSN")
	set status = fileObj.CopyFrom(x12MsgReq.streamContainer.Stream)
	$$$TRACE("Copy status" _ status _", stream size: " _ x12MsgReq.streamContainer.Stream.Size)
	Do fileObj.Close()
	$$$TRACE("File size:" _ ##class(%File).GetFileSize(dataDirec _  flNm))

	if ('(##class(%File).Exists(dataDirec _  flNm))) || (##class(%File).GetFileSize(dataDirec _  flNm) = 0)
	{
		return $$$ERROR($$$GeneralError,"File does not exists or size is 0")
	}

	try {
      // Prepare and log the call
      // Append the city to the URL configured for adapter
      Set tURL=..Adapter.URL_"?operation=RDP&fileName="_flNm_"&transaction="_ x12MsgReq.transactionType_"&rulePath="_rulesDirec_"&filePath="_dataDirec_"&SessionId="_x12MsgReq.SessionID

      // Execute the call
      Set tSC=..Adapter.GetURL(tURL,.tHttpResponse)
      $$$TRACE(tURL _ " call to GetURL: " _ tSC)
      Quit:$$$ISERR(tSC)

      // Return the response
      If $$$ISERR(tSC)&&$IsObject(tHttpResponse)&&$IsObject(tHttpResponse.Data)&&tHttpResponse.Data.Size 
      {
         Set tSC=$$$ERROR($$$EnsErrGeneral,$$$StatusDisplayString(tSC)_":"_tHttpResponse.Data.Read())
      }


      If $IsObject(tHttpResponse) {
	      set retStr = tHttpResponse.Data.Read()
         $$$TRACE("Response: " _ $L(retStr) _ ", " _ tHttpResponse.StatusLine_ ", " _ tHttpResponse.StatusCode_ ", " _ tHttpResponse.ContentLength)
			#dim jsonObj as %DynamicAbstractObject = {}.%FromJSON(retStr) 
			$$$TRACE("JSON: " _ jsonObj.%ToJSON())
			if (jsonObj.status = "PASS")
			{
				$$$TRACE("PASS")
			}
			else
			{
				$$$TRACE("VALIDATION FAILED")
			}
			set pResp.jsonMessage = jsonObj
      }
   }catch ex{
	   $$$LOGERROR("Exception: " _ ex)
       set pResp.respMessage = retStr
   }
   Do ##class(%File).Delete(dataDirec _  flNm)
   Quit tSC

Set tProperty = ""  For { Set tProperty = $$$comMemberNext(%class,$$$cCLASSproperty,tProperty)  Quit:""=tProperty
	// Look for datatypes that are of type Ens.DataType.ConfigName, or a subclass
	$$$comMemberKeyGetLvar(tRuntimeType,%class,$$$cCLASSproperty,tProperty,$$$cPROPruntimetype)
	If ($$$getClassType(tRuntimeType)=$$$cCLASSCLASSTYPEDATATYPE)
	 && ((tRuntimeType="Ens.DataType.ConfigName") || $$IsDerivedFrom^%occLibrary(tRuntimeType,"Ens.DataType.ConfigName")) {
		$$$GENERATE("	If pItem.GetModifiedSetting("""_tProperty_""",.tValue) Do:tValue'="""" ..makeConnections(tValue,.pArray,"""_tRuntimeType_""")")
	}
}
$$$GENERATE("	If pItem.GetModifiedSetting(""AlertOnError"",.tValue),+tValue { Set pArray(""Ens.Alert"")="""" }")
$$$GENERATE("	ElseIf pItem.GetModifiedSetting(""AlertOnError"",.tValue) { Kill pArray(""Ens.Alert"") }")
$$$GENERATE("	Quit")
Quit $$$OK

For i=1:1:$L(pConfigNames,",") {
	Set tConfigName = $ZStrip($P(pConfigNames,",",i),"<>W")

	// For ConfigNames that use template replacement, don't include them unless it's a canonical value
	Continue:pConfigNameType="Ens.DataType.ConfigNameTemplate"&&'##class(Ens.DataType.ConfigNameTemplate).IsCanonical(tConfigName)

	Set:tConfigName'="" pArray(tConfigName)=""
}
